import React,{useEffect,useState} from 'react';
import {useAuth} from '../context/AuthContext';
import {dashboardAPI,authAPI,inventoryAPI,progressionAPI} from '../services/api';
import ImageWithFallback from '../components/ImageWithFallback';
import {resolveItemImage} from '../utils/itemAssets';
export default function ProfilePage(){
 const {user,balance}=useAuth(); const [stats,setStats]=useState(null); const [avatarSaving,setAvatarSaving]=useState(false); const [message,setMessage]=useState('');
 useEffect(()=>{(async()=>{try{const [h,i,p]=await Promise.all([dashboardAPI.getHistory(),inventoryAPI.getInventory(),progressionAPI.getOverview()]);const history=h.data||[];const openings=history.filter(x=>x.type==='opening');const upgrades=history.filter(x=>x.type==='upgrade');const best=openings.reduce((a,x)=>Number(x.itemValue||0)>Number(a?.itemValue||0)?x:a,null);const invValue=(i.data||[]).reduce((s,x)=>s+Number(x.item?.virtual_value||0)*Number(x.quantity||0),0);setStats({cases:openings.length,upgrades:upgrades.length,invValue,best,progression:p.data})}catch(e){console.error(e);setStats({cases:0,upgrades:0,invValue:0,best:null,progression:null})}})()},[]);
 const handleAvatarChange=e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){setMessage('Choisis une image JPG, PNG ou WEBP.');return}setAvatarSaving(true);setMessage('');const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=async()=>{const size=256,canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d'),scale=Math.max(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);try{await authAPI.updateAvatar(canvas.toDataURL('image/webp',.82));setMessage('Photo de profil mise à jour.');setAvatarSaving(false);window.location.reload()}catch(err){setMessage(err.response?.data?.detail||'Impossible de mettre à jour la PP.');setAvatarSaving(false)}};img.src=reader.result};reader.readAsDataURL(file)};
 if(!stats)return <div className="container py-5"><div className="progression-loading"><div className="spinner-border"/></div></div>;
 const best=stats.best, p=stats.progression, color=user?.name_color&&user.name_color!=='white'?user.name_color:undefined;
 return <div className="container profile-premium"><section className="profile-hero"><div className="profile-identity"><div className="profile-avatar-wrap"><ImageWithFallback src={user?.avatar_url||'/images/avatars/default.png'} alt="Avatar" className="profile-avatar-large"/></div><div><span className="section-kicker">WELLCASE / PLAYER CARD</span><h1 style={{color}}>{user?.username||'Player'}</h1><div className="profile-badges">{p?.cosmetics?.badge&&<span>{p.cosmetics.badge}</span>}{(p?.prestige?.prestige||0)>0&&<span>PRESTIGE {p.prestige.prestige}</span>}</div><p>Ta progression, ton arsenal et ton meilleur drop en un coup d’œil.</p></div></div><label className="profile-avatar-button">{avatarSaving?'ENREGISTREMENT…':'CHANGER MA PP'}<input type="file" accept="image/*" hidden onChange={handleAvatarChange} disabled={avatarSaving}/></label></section>{message&&<div className="inline-notice">{message}</div>}
 <section className="profile-stat-grid"><div><span>BANKROLL</span><strong>{Number(balance).toLocaleString('fr-FR')} €</strong></div><div><span>CAISSES OUVERTES</span><strong>{stats.cases}</strong></div><div><span>UPGRADES</span><strong>{stats.upgrades}</strong></div><div><span>INVENTAIRE</span><strong>{stats.invValue.toLocaleString('fr-FR')} €</strong></div></section>
 <section className="profile-panels"><article className="profile-best-drop"><div><span className="section-kicker">BEST DROP</span><h2>{best?.itemName||'Pas encore de drop'}</h2><strong>{best?Number(best.itemValue).toLocaleString('fr-FR')+' €':'—'}</strong></div>{best&&<ImageWithFallback src={resolveItemImage({name:best.itemName,image_url:best.itemImageUrl})} alt={best.itemName} className="profile-best-image"/>}</article><article className="profile-progression"><span className="section-kicker">PROGRESSION</span><h2>Niveau {p?.level||1}</h2><div className="profile-xp"><i style={{width:`${Math.min(100,((p?.xp||0)%500)/5)}%`}}/></div><div className="profile-progress-line"><span>{p?.xp||0} XP</span><span>Prestige {p?.prestige?.prestige||0}</span></div><p>{p?.cosmetics?.pass_complete?'Battle Pass terminé · nom doré débloqué.':'Continue tes quêtes pour débloquer les cosmétiques.'}</p></article></section></div>
}
